import { writeFileSync } from 'node:fs';
import { clinicSearchDocs } from '../src/data/clinical/searchDocs';

/** Snapshot the clinical search entries so the search palette stays light (see searchDocs.ts). */
const docs = clinicSearchDocs();
const rows = docs.map((d) => `  ${JSON.stringify(d)},`).join('\n');
const body = [
  '// Generated by scripts/gen-clinic-search.ts — do not edit; run `npm run export:data`.',
  "import type { SearchDoc } from '../learning/searchIndex';",
  '',
  'export const CLINIC_SEARCH_DOCS: SearchDoc[] = [',
  rows,
  '];',
  '',
].join('\n');
writeFileSync(new URL('../src/data/clinical/searchLite.generated.ts', import.meta.url), body, 'utf8');
console.log(`clinic search: ${docs.length} entries`);
